-- Add comprehensive attraction set (map pins) for all 16 regions
on conflict (id) do nothing;

-- Normalize boabeng-fiema region label to canonical name
update public.destinations set region = 'Bono East' where id = 'boabeng-fiema-monkey-sanctuary';

-- Append new attraction ids to their region records so region modals list them
update public.regions set destinations = destinations || '["kwame-nkrumah-mausoleum"]' where id = 'greater-accra';
update public.regions set destinations = destinations || '["manhyia-palace", "lake-bosomtwe", "ahwiaa-woodcarving-village"]' where id = 'ashanti';
update public.regions set destinations = destinations || '["fort-apollonia", "ankasa-forest-reserve", "sekondi-takoradi-beach"]' where id = 'western';
update public.regions set destinations = destinations || '["techiman-history-museum"]' where id = 'bono';
update public.regions set destinations = destinations || '["kintampo-waterfalls"]' where id = 'bono-east';
update public.regions set destinations = destinations || '["gbewaa-palace"]' where id = 'northern';
update public.regions set destinations = destinations || '["navrongo-basilica", "bolgatanga-basketry-village", "nania-slave-route"]' where id = 'upper-east';
update public.regions set destinations = destinations || '["mount-gemi", "tagbo-falls"]' where id = 'volta';
update public.regions set destinations = destinations || '["bunso-eco-park"]' where id = 'eastern';
update public.regions set destinations = destinations || '["dambai-lake-volta"]' where id = 'oti';
update public.regions set destinations = destinations || '["gambaga-escarpment-lookout"]' where id = 'north-east';
update public.regions set destinations = destinations || '["wa-naa-palace"]' where id = 'upper-west';
update public.regions set destinations = destinations || '["sefwi-wiawso-palace"]' where id = 'western-north';
update public.regions set destinations = destinations || '["ahafo-cocoa-forest"]' where id = 'ahafo';
